import jsonimport osimport certifiimport pymongofrom dotenv import load_dotenvfrom flask import Flask, render_template, request, redirect, Responseload_dotenv()MONGO_URI = os.getenv('MONGO_URI')# Using certifi to prevent SSL certificate verification errors on WSL/Linuxclient = pymongo.MongoClient(MONGO_URI, tlsCAFile=certifi.where())db = client['assignment_db']collection = db['users']app = Flask(__name__)# Task 1: API Endpoint@app.route('/api', methods=['GET'])def get_api_data():    try:        with open('data.json', 'r') as f:            data = json.load(f)        return Response(json.dumps(data), mimetype='application/json')    except:        return Response(json.dumps({'error': 'data.json not found'}), status=404, mimetype='application/json')# Task 2: Form Handling@app.route('/', methods=['GET', 'POST'])def home():    error = None    if request.method == 'POST':        name = request.form.get('name')        email = request.form.get('email')        if not name or not email:            error = 'Please fill out all fields.'        elif '@' not in email or '.' not in email:            error = 'Please enter a valid email address.'        else:            form_data = dict(request.form)            collection.insert_one(form_data)            return redirect('/success')    return render_template('form.html', error=error)@app.route('/success')def success():    return render_template('success.html')if __name__ == '__main__':    app.run(debug=True)